B.byn=new A.aV(B.aU,["bilgi","Ana Ekran Nedir?","T\xfcm servis operasyonunuzun \xf6zet g\xf6r\xfcn\xfcm\xfcd\xfcr. Toplam \u015fof\xf6r, \xf6\u011frenci, aktif servis ve bekleyen devams\u0131zl\u0131k say\u0131lar\u0131n\u0131 buradan g\xf6rebilirsiniz."],t.l)
B.byp=new A.aV(B.aU,["adim","\u0130statistik Kartlar\u0131",'\xdcstteki kartlara t\u0131klayarak o b\xf6l\xfcme h\u0131zl\u0131ca ge\xe7ebilirsiniz. \xd6rne\u011fin "Servisler" kart\u0131na t\u0131klay\u0131nca servis y\xf6netim ekran\u0131 a\xe7\u0131l\u0131r.'],t.l)
B.bzc=new A.aV(B.aU,["adim","Canl\u0131 Harita",'Harita b\xf6l\xfcm\xfcnde \u015fof\xf6rlerin anl\u0131k konumlar\u0131n\u0131 g\xf6rebilirsiniz. "Tam Ekran" butonuyla haritay\u0131 b\xfcy\xfctebilirsiniz.'],t.l)
B.bz0=new A.aV(B.aU,["ipucu","Proje Se\xe7imi","Sol \xfcstteki proje se\xe7iciden aktif projeyi de\u011fi\u015ftirebilirsiniz. Her proje kendi \xf6\u011frenci, \u015fof\xf6r ve servis listesine sahiptir."],t.l)
B.bys=new A.aV(B.aU,["uyari","Bekleyen Devams\u0131zl\u0131klar","Ana sayfada bekleyen devams\u0131zl\u0131k say\u0131s\u0131 k\u0131rm\u0131z\u0131 g\xf6steriliyorsa velilerin g\xf6nderdi\u011fi devams\u0131zl\u0131k bildirimleri var demektir. Hemen kontrol edin."],t.l)
B.bgB=s([B.byn,B.byp,B.bzc,B.bz0,B.bys],t.SN)
B.byI=new A.aV(B.aU,["bilgi","Servis Nedir?",'"1 Servis = 1 \u015eof\xf6r = 1 Ara\xe7" mant\u0131\u011f\u0131yla \xe7al\u0131\u015f\u0131r. Her servis sabah ve ak\u015fam rotas\u0131n\u0131 y\xf6netir. Ak\u015fam rotas\u0131 sabah\u0131n otomatik tersidir.'],t.l)
B.bz9=new A.aV(B.aU,["adim","Servis Ekle",'Sa\u011f \xfcstteki "Servis Ekle" butonuna bas\u0131n. \u015eof\xf6r ad\u0131, telefon, ara\xe7 plakas\u0131 ve kapasiteyi girin. Kaydetti\u011finizde \u015fof\xf6r hesab\u0131 ve ara\xe7 kayd\u0131 otomatik olu\u015fur.'],t.l)
B.byQ=new A.aV(B.aU,["adim","\u015eof\xf6r Giri\u015fi",'Kaydedilen \u015fof\xf6r, "Kullan\u0131c\u0131 Ad\u0131" ve "Ge\xe7ici \u015eifre" ile uygulamaya giri\u015f yapabilir. \u0130lk giri\u015fte \u015fifresini de\u011fi\u015ftirmesi gerekir.'],t.l)
B.byy=new A.aV(B.aU,["ipucu","Belgeler","TC Kimlik, Ehliyet S\u0131n\u0131f\u0131, SRC Belgesi ve Psikoteknik Tarihi form alanlar\u0131na girerek kaydedebilirsiniz. Bu bilgiler \u015fof\xf6r profilinde g\xf6r\xfcn\xfcr."],t.l)
B.bz3=new A.aV(B.aU,["uyari","Pasif Yapma",'\u015eof\xf6r\xfc silmek yerine "Pasif Yap" butonunu kullan\u0131n. Bu \u015fekilde ge\xe7mi\u015f servis kay\u0131tlar\u0131 korunur, \u015fof\xf6r uygulamaya giremez hale gelir.'],t.l)
B.bkQ=s([B.byI,B.bz9,B.byQ,B.byy,B.bz3],t.SN)
B.bzb=new A.aV(B.aU,["bilgi","Kay\u0131tlar Nedir?","\xd6\u011frenci ve veli bilgilerinin merkezi y\xf6netim ekran\u0131d\u0131r. S\xf6zle\u015fme durumunu, atanan servisi ve ayl\u0131k \xfccreti buradan g\xf6rebilirsiniz."],t.l)
B.byJ=new A.aV(B.aU,["adim","Kay\u0131t Ekle",'"Kay\u0131t Ekle" butonuna bas\u0131n. Y\xfcz y\xfcze kay\u0131t formunda \xf6\u011frenci ve veli bilgilerini girin. Adres girince sistem fiyat\u0131 otomatik hesaplar.'],t.l)
B.bz2=new A.aV(B.aU,["adim","Durum Filtreleme",'Dropdown men\xfcden "Bekliyor", "Onayl\u0131" veya "\u0130mzal\u0131" se\xe7erek kay\u0131tlar\u0131 filtreleyebilirsiniz.'],t.l)
B.byP=new A.aV(B.aU,["ipucu","Veli Hesab\u0131","\xd6\u011frenci kaydedildi\u011finde veli i\xe7in otomatik kullan\u0131c\u0131 hesab\u0131 olu\u015fturulur. Telefon numaras\u0131 kullan\u0131c\u0131 ad\u0131, sistem rastgele \u015fifre \xfcretir."],t.l)
B.byA=new A.aV(B.aU,["uyari","Servise Atama",'\xd6\u011frenciyi servise atamak i\xe7in \xf6\u011frenci detay\u0131ndan "Servis" alan\u0131n\u0131 g\xfcncelleyin. Atama yap\u0131lmadan \u015fof\xf6r \xf6\u011frenciyi g\xf6remez.'],t.l)
B.bfc=s([B.bzb,B.byJ,B.bz2,B.byP,B.byA],t.SN)
B.byG=new A.aV(B.aU,["bilgi","S\xf6zle\u015fme Sistemi","Her firma kendi s\xf6zle\u015fme \u015fablonlar\u0131n\u0131 olu\u015fturabilir. Farkl\u0131 projeler i\xe7in farkl\u0131 \u015fablonlar kullan\u0131labilir."],t.l)
B.byV=new A.aV(B.aU,["adim","\u015eablon Olu\u015ftur",'"Yeni \u015eablon" butonuna bas\u0131n, \u015fablon ad\u0131n\u0131 girin. Sistem otomatik olarak zorunlu maddeleri (KVKK, Emniyet Kemeri) ekler.'],t.l)
B.byk=new A.aV(B.aU,["adim","Madde Y\xf6netimi",'"Haz\u0131r Maddeler" sekmesinde istedi\u011finiz maddeleri a\xe7\u0131p kapatabilirsiniz. Zorunlu maddeler (k\u0131rm\u0131z\u0131 etiketli) kapat\u0131lamaz.'],t.l)
B.byS=new A.aV(B.aU,["adim","Firma Bilgileri",'"Firma Bilgileri" sekmesinde firma ad\u0131, yetkili, adres ve vergi bilgilerini girin. Bu bilgiler PDF s\xf6zle\u015fmede otomatik g\xf6r\xfcn\xfcr.'],t.l)
B.byR=new A.aV(B.aU,["adim","PDF Olu\u015ftur",'"PDF & G\xf6nder" sekmesinden PDF olu\u015fturabilir, WhatsApp ile payla\u015fabilir veya metni kopyalayabilirsiniz.'],t.l)
B.byc=new A.aV(B.aU,["ipucu","Proje Bazl\u0131 \u015eablon","Her projeye farkl\u0131 \u015fablon atayabilirsiniz. Projeler \u2192 ilgili proje \u2192 S\xf6zle\u015fme sekmesinden \u015fablon se\xe7in."],t.l)
B.bh9=s([B.byG,B.byV,B.byk,B.byS,B.byR,B.byc],t.SN)
B.byM=new A.aV(B.aU,["bilgi","Rota Sistemi","3 sekme: Rotalar (\u015fof\xf6r bazl\u0131), Atamas\u0131zlar (servise atanmam\u0131\u015f \xf6\u011frenciler) ve Servisler (proje bazl\u0131 servisler)."],t.l)
B.bz8=new A.aV(B.aU,["adim","Sabah / Ak\u015fam Ayr\u0131m\u0131","Her \u015fof\xf6r\xfcn alt\u0131nda sabah ve ak\u015fam g\xfczergah\u0131 ayr\u0131 g\xf6sterilir. Ak\u015fam rotas\u0131 sabah\u0131n otomatik tersidir \u2014 Ev\u2192Okul, Okul\u2192Ev."],t.l)
B.byj=new A.aV(B.aU,["adim","Filtreler","\xdcstteki Sabah/Ak\u015fam/\xd6\u011fle butonlar\u0131na t\u0131klayarak sadece o tipteki rotalar\u0131 g\xf6rebilirsiniz."],t.l)
B.bz_=new A.aV(B.aU,["uyari","Atamas\u0131z \xd6\u011frenciler",'"Atamas\u0131zlar" sekmesinde servise atanmam\u0131\u015f \xf6\u011frenciler g\xf6r\xfcn\xfcr. Bu \xf6\u011frencileri bir servise atayana kadar \u015fof\xf6r g\xf6remez.'],t.l)
B.byE=new A.aV(B.aU,["ipucu","Haritada G\xf6ster","\xd6\u011frenci adresinin yan\u0131ndaki harita ikonuna t\u0131klayarak konumu Google Maps'ta g\xf6rebilirsiniz."],t.l)
B.bhk=s([B.byM,B.bz8,B.byj,B.bz_,B.byE],t.SN)
B.byK=new A.aV(B.aU,["bilgi","Canl\u0131 Takip Haritas\u0131","\u015eof\xf6rlerin anl\u0131k GPS konumlar\u0131n\u0131 haritada g\xf6rebilirsiniz. \u015eof\xf6r uygulamada aktif servis ba\u015flatt\u0131\u011f\u0131nda konumu otomatik g\xfcncellenir."],t.l)
B.byU=new A.aV(B.aU,["adim","\u015eof\xf6r \u0130konu","Haritadaki ara\xe7 ikonuna t\u0131klay\u0131nca \u015fof\xf6r ad\u0131, plaka ve son g\xfcncelleme zaman\u0131 g\xf6r\xfcn\xfcr."],t.l)
B.byY=new A.aV(B.aU,["adim","\xd6\u011frenci Duraklar\u0131","\xd6\u011frenci ikonlar\u0131na t\u0131klay\u0131nca o \xf6\u011frencinin ad\u0131 ve bindi/binmedi durumu g\xf6r\xfcn\xfcr."],t.l)
B.byO=new A.aV(B.aU,["ipucu","Otomatik Takip","Harita 30 saniyede bir otomatik g\xfcncellenir. Manuel yenilemek i\xe7in sa\u011f \xfcstteki yenile butonunu kullan\u0131n."],t.l)
B.byd=new A.aV(B.aU,["uyari","Konum Kapal\u0131ysa","\u015eof\xf6r\xfcn konumu g\xf6z\xfckm\xfcyorsa uygulamada konum izni verilmemi\u015f olabilir. \u015eof\xf6re uygulamada konumu a\xe7mas\u0131n\u0131 s\xf6yleyin."],t.l)
B.b0K=s([B.byK,B.byU,B.byY,B.byO,B.byd],t.SN)
B.bya=new A.aV(B.aU,["bilgi","Raporlar Ekran\u0131","\xd6\u011frenci say\u0131lar\u0131, \u015fof\xf6r durumlar\u0131, devams\u0131zl\u0131k istatistikleri ve gelir \xf6zetini bu ekranda g\xf6rebilirsiniz."],t.l)
B.byZ=new A.aV(B.aU,["adim","Excel Aktar",'"Excel Aktar" butonuna bas\u0131nca \xf6\u011frenci ve \u015fof\xf6r listesi Excel format\u0131nda haz\u0131rlan\u0131r.'],t.l)
B.byo=new A.aV(B.aU,["adim","Metin Kopyala","\xd6\u011frenci Listesi, \u015eof\xf6r Listesi, Devams\u0131zl\u0131k Raporu ve Genel \xd6zet butonlar\u0131 bilgileri panoya kopyalar. WhatsApp'a yap\u0131\u015ft\u0131rabilirsiniz."],t.l)
B.bz6=new A.aV(B.aU,["ipucu","Devams\u0131zl\u0131k Raporu","Son 30 g\xfcnl\xfck devams\u0131zl\u0131klar listelenir. Velinin g\xf6nderdi\u011fi bildirimler burada g\xf6r\xfcn\xfcr."],t.l)
B.bf_=s([B.bya,B.byZ,B.byo,B.bz6],t.SN)
B.bz5=new A.aV(B.aU,["bilgi","Ayarlar","Firma profili, bildirim ayarlar\u0131, kullan\u0131c\u0131 y\xf6netimi ve sistem yap\u0131land\u0131rmas\u0131n\u0131 buradan yapabilirsiniz."],t.l)
B.byt=new A.aV(B.aU,["adim","Firma Profili","Firma ad\u0131, logo, adres ve ileti\u015fim bilgilerini g\xfcncelleyin. Bu bilgiler s\xf6zle\u015fme PDF'lerinde ve kay\u0131t formlar\u0131nda otomatik kullan\u0131l\u0131r."],t.l)
B.byB=new A.aV(B.aU,["adim","Kullan\u0131c\u0131 Y\xf6netimi","Y\xf6netici, \u015fof\xf6r ve veli hesaplar\u0131n\u0131 buradan y\xf6netebilirsiniz. Hesap ask\u0131ya alma ve silme i\u015flemleri burada yap\u0131l\u0131r."],t.l)
B.byF=new A.aV(B.aU,["ipucu","Bildirimler","Devams\u0131zl\u0131k bildirimi, \xf6\u011frenci bindi/indi ve servis ba\u015flad\u0131 bildirimlerini a\xe7\u0131p kapatabilirsiniz."],t.l)
B.bho=s([B.bz5,B.byt,B.byB,B.byF],t.SN)
B.bym=new A.aV(B.aU,["bilgi","Fiyat Sistemi","\xdc\xe7 farkl\u0131 fiyatland\u0131rma y\xf6ntemi: Mahalle bazl\u0131, \u0130l\xe7e bazl\u0131 ve Kilometre bazl\u0131. Veli adresini girince sistem otomatik fiyat hesaplar."],t.l)
B.bz4=new A.aV(B.aU,["adim","Mahalle / \u0130l\xe7e Bazl\u0131",'"Fiyat Ekle" sekmesinde il\xe7e ve mahalle se\xe7ip fiyat girin. Veli o mahalleden kay\u0131t yapt\u0131r\u0131nca bu fiyat otomatik atan\u0131r.'],t.l)
B.by8=new A.aV(B.aU,["adim","Km Bazl\u0131 Fiyat",'"Km Bazl\u0131" sekmesinde iki y\xf6ntem var: Kademe (0-5km: 1500 TL) veya Birim fiyat (Baz + km\xd7fiyat form\xfcl\xfc).'],t.l)
B.byW=new A.aV(B.aU,["ipucu","\xd6ncelik S\u0131ras\u0131","Sistem \xf6nce mahalleye bakar, bulamazsa il\xe7eye, sonra km bazl\u0131 hesaplar. En spesifik fiyat ge\xe7erlidir."],t.l)
B.byl=new A.aV(B.aU,["uyari","Fiyat S\xf6zle\u015fmeye \u0130\u015flenir","Hesaplanan fiyat otomatik olarak s\xf6zle\u015fmeye ve PDF'e i\u015flenir. Velinin onaylamas\u0131 gereken \xfccret buradaki fiyatt\u0131r."],t.l)
B.beO=s([B.bym,B.bz4,B.by8,B.byW,B.byl],t.SN)
B.byH=new A.aV(B.aU,["bilgi","\u015eof\xf6r Paneli","Bu ekran \u015fof\xf6rlere \xf6zeldir. \xd6\u011frenci listesi, g\xfczergah, devams\u0131zl\u0131k bildirimi ve canl\u0131 navigasyon \xf6zelliklerini i\xe7erir."],t.l)
B.bz7=new A.aV(B.aU,["adim","Servisi Ba\u015flat",'Turuncu "Servisi Ba\u015flat" butonuna bas\u0131nca konumunuz yay\u0131nlanmaya ba\u015flar ve veliler sizi haritada g\xf6r\xfcr.'],t.l)
B.byh=new A.aV(B.aU,["adim","\xd6\u011frenci Listesi","Her \xf6\u011frencinin yan\u0131ndaki \u2713 butonuna basarak \xf6\u011frencinin bindi bilgisini kaydedin. Veli anl\u0131k bildirim al\u0131r."],t.l)
B.byg=new A.aV(B.aU,["adim","Devams\u0131zl\u0131k",'\xd6\u011frenci gelmeyecekse "Devams\u0131z" butonuna bas\u0131n. Veliye otomatik bildirim gider.'],t.l)
B.by9=new A.aV(B.aU,["ipucu","Navigasyon","\xd6\u011frenci adresine t\u0131klayarak Google Maps navigasyonu a\xe7abilirsiniz."],t.l)
B.byx=new A.aV(B.aU,["uyari","\xc7oklu G\xf6rev","Sabah ve ak\u015fam farkl\u0131 projelerde g\xf6reviniz varsa, giri\u015f yap\u0131nca proje se\xe7im ekran\u0131 a\xe7\u0131l\u0131r. Do\u011fru projeyi se\xe7in."],t.l)
